# Extract connected components with bounding boxes, and infer their output coordinates by order only.
def get_components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); cs=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]!=2 or (r,c) in seen: continue
       stack=[(r,c)];seen.add((r,c)); cells=[]
       while stack:
        y,x=stack.pop();cells.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         n=(y+dy,x+dx)
         if 0<=n[0]<h and 0<=n[1]<w and grid[n[0]][n[1]]==2 and n not in seen:
          seen.add(n);stack.append(n)
       cs.append(cells)
    return sorted(cs,key=min)
